// Pictish knot  by celifan 
// https://www.shadertoy.com/view/lcfBDM
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License
// Contact the author for other licensing options
//
// Piecewise modeling of a Pictish knot.
// Explicit heighfield modeling using linear & quadratic functions + a hint of smoothstep.
//
//

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 2   // make this 2 or 3 for antialiasing
#endif
// For convenience positions are expressed as integers in a [_n x _n] grid 
const float s = .9; //  grid width in normalize pix coordinates

// transformation to apply to vec2 in [_n X _n ] -->  normalize pix coordinates
#define V(x,y) (vec2(float(x),float(y))*s/_n)
#define S(x) ((float(x))*s/_n) 
///
#define SC 1.0
const float PI = 3.1415926;
float _ar; //aspect ratio.
const float _n = 12.0; // grid num subdivision.
float _pixSize ;
const float _lw =1.0*SC; // default line width in pixels
const float _ps =2.0*SC; // default point size in pixels

// global offset screen space.
vec2 _pOffset = vec2(0.1);
vec2 _cs; // cos/sin of the main rotation 

// construction constants
const float m= sqrt(2.0)/(3.0+sqrt(2.0));
const float r = S(6)*m;
const float ri2 = r/2.0;
const float rs2 = r*sqrt(2.0);
const float ris2 = r/sqrt(2.0);
const vec2 c =vec2(S(6),r);
//
const float d = r/2.0; 
const float di2 =d/2.0;

const float ds2 = d*sqrt(2.0);
const float dis2 = d/sqrt(2.0);

// ligthing
const vec3  _sun_dir = vec3(0.485071250, 0.485071250, 0.72760687);


// default colors.
const vec3 _c0 = vec3(.95,.92,.9);
const vec3 _c1 =  vec3(0.4,0.4,0.4);
const vec3 _cBlue = vec3(0.0,0.36,1.0);
const vec3 _c2 = vec3(.9,.9,.9);
const vec3 _pc = vec3( .9,0.3,0.0); 
float _f ;
// animation
float _q0T = 3.0051;


#define CS(a) vec2(cos(a), sin(a))
// cs = vec2(cos(rotAngle), sin(rotAngle));
vec2 R(vec2 v, vec2 cs)
{
    return mat2(cs.x, cs.y, -cs.y, cs.x)*v;
}


float height(vec2 p, float t,int q, inout vec3 pixel);

float calcShadow( in vec3 ro, in vec3 rd,float tq, int q )
{
    vec3 scratch;
    float res = 1.0;
    float t = 0.01;

    for( int i=min(0,iFrame); i<64; i++ )
    {
        vec3  pos = ro + t*rd;
        float hei = pos.z-height( pos.xy,tq,q,scratch );

        res = min( res, 12.0*(hei/t));
        if( res<0.01 || pos.z>d+di2 ) break;
        t += clamp( hei, 0.001, 0.01 );
    }
    return  clamp( res, 0.0, 1.0 );
}

vec3 lighting(vec3 pos, vec3 nor, float t, int q)
{

    vec3 c1 = vec3(1.0,.686,0.475);
    vec3 c11 = vec3(1.0,.451,0.07);
    vec3 c2 = vec3(.655,.827,1.0);

    vec3 key_dir = vec3(R(_sun_dir.xy,_cs),_sun_dir.z-.25);

    vec3 mat  =  pos.z <-di2+0.001 ? c1*.1 :vec3(.2) ;
    // 
    float key = clamp(dot( nor, key_dir ), 0.0, 1.0 );

    float sha =iTime>60.0 ? calcShadow( pos, key_dir, t,q):1.0;
    sha = mix(1.0,sha,clamp((iTime-60.0)/3.0,0.0,1.0));
    float fil = clamp( 0.5 + 0.5*nor.z, 0.0, 1.0 );
    float bck =  clamp( dot(normalize(vec3(-key_dir.x,-key_dir.y,-di2)),nor), 0.0, 1.0 );
    //
    vec3 lin = 2.0*mix(c11,1.5*c2,fil);
    lin += key*5.0*c1*sha;
    lin += bck*1.0*vec3(1.0,1.0,1.0);

    return mat*lin;
}


// 3D noise function (IQ)
float noise(vec3 p)
{
	vec3 ip=floor(p);
    p-=ip; 
    vec3 s=vec3(7,157,113);
    vec4 h=vec4(0.,s.yz,s.y+s.z)+dot(ip,s);
    p=p*p*(3.-2.*p); 
    h=mix(fract(sin(h)*43758.5),fract(sin(h+s.x)*43758.5),p.x);
    h.xy=mix(h.xz,h.yw,p.y);
    return mix(h.x,h.y,p.z); 
}



float height(vec2 p, float t,int q, inout vec3 pixel)
{
    if ( any(lessThan(p,V(0,0))) || any(greaterThan(p,V(12,12))))
        return -di2;

    int quadrant  = int(t/(_q0T));
    float qToMul[4] = float[4](0.0,3.0,1.0,2.0);
    float mul = qToMul[q];    
    t-=mul*_q0T;


    float sch= 1.0/2.0;
    vec2 hn = vec2(-di2,-di2); // (h,h0) // need 2 levels of height for animation. 
    vec2 cc = V(0,0) + vec2(sqrt(2.0)+1.0,1.0)*d;

    //

    float oparm , param=0.0;


    //center of arc ac with 2 lines tangency contraints
    vec2 o = c-(c.y-di2)*vec2(1.0);
    float a = (2.0/sqrt(2.0)-1.0);
    vec2 ac = o+a*(r+di2)*vec2(sqrt(2.0)/2.0) +(r+di2)*vec2(-1.0,1.0)*sqrt(2.0)/2.0;

    // ***
    vec2 dn = -vec2(sqrt(2.0)/2.0);
    vec2 C = c + -dn*(r+d);
    vec2 O = C - vec2(1.0,-1.0)*dis2*.5;

    float l= dot(ac-C,dn);
    float param_p = dot(p-C,dn); // param from o

    bool mask = param_p >=0.0 && param_p<=l;
    vec2 eC = C+param_p*dn;
    float  fh = length(p-eC);
    mask = mask && fh<di2;
    float h = sqrt(di2*di2-fh*fh)*sch;
    float paT =  r+d; // dist to heighest point
    //->
    float h1 = smoothstep(S(1.5),S(0),abs( paT-(param +param_p)))*di2;  

    h += h1; 
    bool u =  h >hn.x && mask;
    oparm = u ? param +param_p :oparm; 
    hn =  u ? vec2(h,-di2) : hn;

    param =l;
    // ***
    // *************

    vec2 acp = p-ac;
    float lacp = length(acp);
    //
    C= C+dn*l;
    vec2 C1= ac+ vec2(0.0,-1.0)*(r+di2);
    eC = ac+ (r+di2)*acp/lacp;
    mask =  dot(acp,vec2(1.0,0.0))>0.0 && 
            dot(acp, (ac-(C)).yx*vec2(1.0,-1.0))<0.0;
    fh = abs(lacp-(r+di2));
    mask = mask && fh <di2;
    h = sqrt(di2*di2-fh*fh)*sch;

    //->
    float paC = (r+di2)*acos(dot(C-ac,acp)/(lacp*length(C-ac)));
    h1 = smoothstep(S(1.5),S(0),abs((param+paC)-paT ))*di2;
    h+=h1;
    u= h >hn.x && mask;    
    //
    float paramO =(r+di2)*acos(dot(C-ac,C1-ac)/(length(C1-ac)*length(C-ac)));


    //
    oparm = u? param+paC: oparm;  
    hn = u ? vec2(h,-di2) : hn;
    param += paramO;

    // ***
    // ********************
    dn = vec2(-1.0,0.0);
    C = ac + vec2(0.0,-(r+di2));
    O = C+vec2(0.0,di2);
    l = C.x-(sqrt(2.0)+1.0)*d;
    paC = dot(p-C,dn);
    vec2 Ol= O+dn*l;
    mask = paC >=0.0 && dot(p,vec2(Ol.y,-Ol.x))>0.0;
    eC = C+paC*dn;  


    fh = length(p-eC);
    mask = mask && fh<di2 && p.x > di2*(sqrt(2.0)+1.0)/sqrt(4.0+2.0*sqrt(2.0));
    h = sqrt(di2*di2-fh*fh)*sch;

    //-> 
    paramO =C.x-(sqrt(2.0)+1.0)*d/2.0;
    vec2 OL = vec2(1.0+sqrt(2.0),1.0)*d; 
    float paramO1 =0.0;

    vec2 Ob = O+vec2(0.0,-d);
    vec2 po = OL+(O.x-OL.x)*vec2(1.0,(1.0)/(1.0+sqrt(2.0)));
    //
    if (dot(p,vec2(OL.y,-OL.x))>0.0)
    {
        vec2 ppo = po-p;
        param_p =param+ C.x-(p.x+(C.y-p.y)*1.0/(ppo.y/ppo.x)); 
    }
    else
    {
        vec2 Ot = OL+ dot(c-OL,vec2(.5));
        vec2 po = OL+ OL* dot(Ot-OL, vec2(1.0))/dot(OL,vec2(1.0));
        vec2 C= OL-vec2(sqrt(2.0)+1.0,1.0)*d/2.0;
        vec2 ppo =po-p;
        float a = dot(ppo, vec2(-1.0,1.0));
        float b = dot(C-po,vec2(-1.0,1.0));
        param_p =param +paramO + (po.x+ ppo.x*b/a-C.x)*sqrt(2.0); 
    }
    //
    u = mask;                                       
    oparm = u ? param_p  :oparm;
    hn = u ? vec2(h,-di2) : hn;
    param += paramO;
    // ***
    // ********************
    O = vec2(1.0+sqrt(2.0),1.0)*d;
    vec2 On = normalize(O);
    vec2 Onp = vec2(On.y,-On.x);
    float hc; //height for pixel belonging to the corner area.
    bool right_corner; bool mid_corner; // left & mid corner areas.
    // round corner symetry remaping
{
    bool left_corner =true;
    vec2 O1 = vec2( sqrt(2.0)+1.0,1.0)*di2;
    vec2 O2= di2*On;
    vec2 O2b = vec2(O2.x,0.0);
    vec2 O2t = O2+ O2.y*vec2(-1.0,1.0)/sqrt(2.0);
    vec2 O2c = (O2b+O2t)/2.0;

    vec2 pt =p;
    // remap other corner to the bottom left corner
    {
        vec2 On1 = vec2(-sqrt(2.0) -sqrt(1.0),1.0)*d;

        vec2 Or = V(12,0)+On1;
        right_corner = p.y>=0.0 && 
                            dot(p-Or,On1)<=0.0 &&
                            dot(p-V(12,0),vec2(1.0))<0.0;

       pt = right_corner ?  vec2(S(12)-p.x ,p.y):p;             

       vec2 Or2 = Or +On1;
       mid_corner = p.y-Or.y>=0.0 && 
                            dot(p-Or2,On1)<0.0 &&
                            dot(p-Or,vec2(1.0))<0.0;

       pt = mid_corner ?  vec2(Or.x-p.x ,p.y-d):pt; 
       left_corner = !mid_corner && !right_corner;
    }

    // On is axis of symetry.
    pt = dot(pt,On)*On +abs(dot(pt,Onp))*Onp;

    float d1 = (di2-pt.y);
    h = dot(pt-O2,On)<0.0 ?-di2: sqrt(di2*di2-d1*d1) ;

    //->cp cpb | cpb1
    vec2 cp = O+dot(pt-O,On)*On;
    //
    float d01 = -dot(pt-O,On)/distance(O,O2c);
    float dl = mix(0.0,distance(O2b,O2t)/2.0, d01);
    //
    vec2 cpb = cp+Onp*dl;
    vec2 cpb1 = cp+Onp*(dl-_pixSize);
    // 
    d1 = di2-cpb.y;
    float hpb =sqrt(di2*di2 - d1*d1);
    d1 = di2-(cpb1.y);
    float hpb1 =sqrt(di2*di2 - d1*d1);
    //
    float gb = (hpb1 - hpb)/_pixSize;
    vec2 tgb = normalize(vec2(1.0,gb));
    //
    d1 = abs(dot(pt-cp,Onp));
    float ux = dl;
    float a = gb/(2.0*ux);

    float dh = -a*d1*d1 +a*ux*ux;
     h= d01<=1.0 && dot(pt -(O-On*_pixSize),vec2(O.y-cpb.y,cpb.x-O.x))<0.0 ? hpb +dh : h;

    ///-->
    vec2 O2_prev = O2;
    O2 = O2+On*di2/3.0;
    float ra = dot(O2-O2c,On)/distance(O2c,O);
    d1 = mix(distance(O2c,O2b),0.0,ra);
    // --> hpt
    // hb
    O2b = O2+Onp*d1;
    d1 = di2-O2b.y;
    float hb = sqrt(di2*di2-d1*d1);
    // hby
    float eps =_pixSize;
    vec2 O2by =O2b -Onp*eps;
    d1 = clamp(di2-O2by.y, -di2,di2);
    float hby = sqrt(di2*di2-d1*d1);
    //
    float gby = (hby-hb)/_pixSize;
    // fit parablola
    vec2 ptp = O2b +Onp*dot(pt-O2b,Onp);
    d1 = distance(ptp,O2);
    ux = distance(O2b,O2);
    a = gby/(2.0*ux);
    dh = -a*d1*d1 +a*ux*ux;
    float hpt = hb+ dh;
    // --> hptx
    // hbx
    vec2 O2bx = O2b+On*_pixSize;
    d1 = di2-O2bx.y;
    float hbx = sqrt(di2*di2-d1*d1);
    // hbxy
    vec2 O2bxy =O2bx -Onp*_pixSize;
    d1 = clamp(di2-O2bxy.y, -di2,di2);
    float hbxy = sqrt(di2*di2-d1*d1);
    //
    float gbxy = (hbxy- hbx)/_pixSize;
    // fit parabola. 
    vec2 ptpx = ptp + On*_pixSize;
    d1 = distance(ptp,O2);
    ux = distance(O2b,O2);
    a = gbxy/(2.0*ux);
    dh = -a*d1*d1 +a*ux*ux;
    float hptx = hbx+ dh ;
    //
    // gradient in ortho dir.
    float gx = (hptx-hpt)/_pixSize;

    vec2 tgx = normalize(vec2(1.0, gx));
    vec2 nv = vec2(tgx.y,-tgx.x);

    // fit ellipse  

    vec2 ptpv = vec2(distance(ptp,V(0,0)),hpt);
    vec2 ptpv1 = vec2(distance(ptp,V(0,0)),hpt) +nv*_pixSize*10.0;
    cp = ptpv -(ptpv1-ptpv)*ptpv.y/(ptpv1.y-ptpv.y);
    ra = distance(cp,ptpv);
    vec2 ptv = vec2(dot(pt-V(0,0),On),0.0);
    //
    vec2 O3 = On*di2;
    float sd1 = distance(O3,pt)-O3.y;
    d1 = dot(pt-O3,Onp);
    dh = sqrt(O3.y*O3.y -d1*d1);

    vec2 O3c = dot(pt-vec2(O3.x,0.0),Onp)>=0.0 ? ptp+On*ptp.y/(ptp.y-On.y)
                                              : O3 +dot(pt-O3,Onp)*Onp -On*dh;
    vec2 O3cv = vec2(dot(O3c,On),0.0);

    float h4 = dot(O3cv-cp,nv);
    float sca = sqrt(ra*ra-h4*h4)/dot(O3cv-cp,tgx);

    vec2 ptvf = vec2(dot(ptv-cp,tgx),dot(ptv-cp,nv));
    vec2 ptv1f = vec2(dot(ptv+vec2(0.0,1.0)-cp,tgx),dot(ptv+vec2(0.0,1.0)-cp,nv));
    ptvf.x*=sca;
    ptv1f.x*=sca;
    vec2 ptvn = normalize(ptv1f-ptvf);
    vec2 ptvfh = ptvf +dot(-ptvf,ptvn)*ptvn;
    dh = length(ptvfh);
    float sq =sqrt(ra*ra-(dh*dh));
    vec2 ptvfc = ptvfh + ptvn*sq;
    ptvfc.x*=1.0/sca;
    vec2 pci =cp + ptvfc.x*tgx + ptvfc.y*nv; 
    float hv = ra>=dh ? distance(pci,ptv) : 0.0;
    float he= hv;
    h = mix(h,he, 1.0-smoothstep(-0.01,0.01, dot(pt-O2,On)));
    hc =h; 
    bool m1 = dot(p-vec2(O3.x,0.0),On)>0.0;
    h =  m1 || (!m1 && sd1<0.0) ? sch*h:  -di2;

    //h1 
    paT = param + distance(di2*vec2(1.0+sqrt(2.0),1.0),c+ (di2+r)*vec2(-1.0,1.0)/sqrt(2.0));
    h1 = 1.5*smoothstep(S(4.3),S(0),abs((param_p)-paT))*di2;


    if ( left_corner)
    {
        mask = pt.y>0.0   && dot(pt-O,On)<0.0;
        h+=  h1;
        u = mask;
        oparm = u ? param_p  :oparm;
        hn = u ? vec2(h,-di2) : hn;
    }
}
    // ***
    // ****************
    O = cc;
    C= O+ vec2(-dis2,+dis2)*.5;
    l= S(6)*sqrt(2.0)-ds2-2.0*d;
    dn = vec2(sqrt(2.0)/2.0);
    paC = dot(p-C,dn); 
    mask = dot(p-O,vec2(1.0))>0.0 && dot(p-O,vec2(O))>0.0 && paC<=l;
    eC = C+paC*dn; 
    fh = length(p-eC);
    mask = mask && fh<di2;
    h = sqrt(di2*di2-fh*fh)*sch;
    //->
    vec2 OCb1= c+vec2(-1.0,1.0)*(ds2+di2/sqrt(2.0));
    paramO =  ((OCb1.x)-(1.0/2.0+1.0/sqrt(2.0))*d )*sqrt(2.0); 

    param_p =dot(p-c,vec2(-1.0))<0.0 ? param+paramO+ distance(OCb1,c+ (p-c)*
                                       dot(OCb1-c,vec2(-1.0,1.0))/dot(p-c,vec2(-1.0,1.0)))
                                      : param_p;                                                                  
    paT = param +paramO;
    float paT1 = param +paramO +(c.x +dis2*2.5 -S(6))*sqrt(2.0)+(S(6)-(c.x-dis2*2.5))*sqrt(2.0);

    h1 = di2*( 1.5*(param_p -paT >0.0 ? 1.0- smoothstep(S(0),S(3),param_p -paT)
                                      : 1.0- smoothstep(S(0),S(4.3),-(param_p -paT)))-
              (1.0- smoothstep(S(0),S(3),abs(param_p -paT1))) );  

    h+=h1;     
    u = h >hn.x && mask;
    oparm = u? param_p :oparm;
    hn = u ? vec2(h,-di2) : hn;
    param += paramO;
    // ***
    // ********************
    // Top corner.

    O = V(6,6)-vec2(0.0,1.0)*d*sqrt(2.0) ;
    vec2 Op =p-O;
    float lOp =length(Op);
    vec2 CL = O+ vec2(-di2,+di2)/sqrt(2.0);
    vec2 CR = vec2(S(6)+S(6)-CL.x, CL.y); 
    // h1
    vec2 OCb2 =V(6,6)+vec2(0.0,-ds2/2.0);
    paramO= (OCb2.x-(c.x-(ds2+di2/sqrt(2.0))))*sqrt(2.0);
    paramO1 = dot(c-OCb2,vec2(1.0,-1.0)/sqrt(2.0));

    if(p.x>S(6))
    {
        param_p = param+paramO+distance(OCb2,c+(p-c)*dot(OCb2-c,vec2(1.0))/dot(p-c,vec2(1.0))); 
    }
    h1 = di2*( 1.5*(1.0- smoothstep(S(0),S(3),abs(param_p-paT)))-
             ( 1.0- smoothstep(S(0),S(3),abs(param_p-paT1))) );  

    {
        float O3r  = On.y*di2;
        vec2 O3 = V(6,6) +vec2(0.0,-O3r*sqrt(2.0));

        vec2 On= vec2(0.0,-1.0);
        vec2 Onp = vec2(On.y,-On.x);

        float dh0 = dot(p-CL,vec2(-1.0,1.0)/sqrt(2.0));
        float dh1 = dot(p-CR,vec2(1.0)/sqrt(2.0));
        h= dot(p-O,Onp) >0.0 ? sqrt(di2*di2-dh0*dh0) :sqrt(di2*di2-dh1*dh1) ;


        //

        float O2Ra = 1.0/3.0;
        vec2 O2 =V(6,6) + (O-V(6,6))*O2Ra;

        vec2 O2l = V(6,6) - V(4,4)*((S(6)-O2.y)/S(4));
        vec2 O2r =  V(6,6) + V(4,-4)*((S(6)-O2.y)/S(4));

        vec2 pt =p;
        float fa = clamp((O2.y-pt.y)/(O2.y-O.y),0.0,1.0);
        vec2 O2lp = mix(O2l,O,fa);
        float d1 = dot(O2lp-CL,vec2(-1.0,1.0)/sqrt(2.0));
        float hO2lp = di2>d1 ? sqrt(di2*di2 -d1*d1):0.0;
        d1 = dot(O2lp+_pixSize*Onp-CL,vec2(-1.0,1.0)/sqrt(2.0));
        float hO2lp1 = di2>d1 ? sqrt(di2*di2 -d1*d1) : 0.0;
        float m= (hO2lp1-hO2lp)/_pixSize;

        d1 = S(6)-pt.x;
        float u = -(S(6)-O2lp.x);
        float a = m/(2.0*u);

        float dh = -a*d1*d1 +a*u*u;
        bool m1 = dot(p-O,vec2(O.y-O2l.y,O2l.x-O.x))<0.0 && 
                  dot(p-O,vec2(O.y-O2r.y, O2r.x-O.x))>0.0;       
        h= m1 ? hO2lp +dh : h;
        // dh
        vec2 O2_prev = O2;
        O2 = O2+ (O-V(6,6))*O2Ra/1.5;

        //--> pt     
        pt = p;
        vec2 ptp = O2 +Onp*abs(dot(pt-O2,Onp));

        fa = clamp((O2_prev.y-O2.y)/(O2_prev.y-O.y),0.0,1.0);
        O2lp = mix(O2l,O,fa);
        d1 = dot(O2lp-CL,vec2(-1.0,1.0)/sqrt(2.0));
        hO2lp = sqrt(di2*di2 -d1*d1);

        d1 = dot(O2lp+_pixSize*Onp-CL,vec2(-1.0,1.0)/sqrt(2.0));
        hO2lp1 = sqrt(di2*di2 -d1*d1);

         m= (hO2lp1-hO2lp)/_pixSize;
        d1 = S(6)-ptp.x;
        u = -(S(6)-O2lp.x);
        a = m/(2.0*u);
        dh = -a*d1*d1 +a*u*u;
        //
        float dh00 = dot(ptp-CL,vec2(-1.0,1.0)/sqrt(2.0));

        float d0= sqrt(di2*di2-dh00*dh00);


        m1 = dot(ptp-O,vec2(O.y-O2l.y,O2l.x-O.x))<0.0 ;     
        float DH =  m1 ? hO2lp+dh: d0;
        // dh1
        vec2 O21 =O2+ On*_pixSize;
        vec2 ptp1 =ptp+  On*_pixSize;

        fa = clamp((O2_prev.y-O21.y)/(O2_prev.y-O.y),0.0,1.0);
        O2lp = mix(O2l,O,fa);

        d1 = dot(O2lp-CL,vec2(-1.0,1.0)/sqrt(2.0));
        hO2lp = sqrt(di2*di2 -d1*d1);
        d1 = dot(O2lp+_pixSize*Onp-CL,vec2(-1.0,1.0)/sqrt(2.0));
        hO2lp1 = sqrt(di2*di2 -d1*d1);

        m= (hO2lp1-hO2lp)/_pixSize;
        d1 = S(6)-ptp1.x;
        u = -(S(6)-O2lp.x);
        a = m/(2.0*u);
        dh = -a*d1*d1 +a*u*u;
        //
        dh00 = dot(ptp1-CL,vec2(-1.0,1.0)/sqrt(2.0));

        d0= sqrt(di2*di2-dh00*dh00) ;
        m1 = dot(ptp1-O,vec2(O.y-O2l.y,O2l.x-O.x))<0.0;
        float DH1 =  m1 ? hO2lp + dh : d0;

        float M = (DH1-DH)/_pixSize;
        vec2 tg = normalize(vec2(1.0,M));
        vec2 nv = vec2(tg.y,-tg.x);

        vec2 ptpv = vec2(S(6)-ptp.y,DH);
        vec2 ptpv1 = vec2(S(6)-ptp.y,DH) +nv*_pixSize*10.0;
        vec2 cp = ptpv -(ptpv1-ptpv)*ptpv.y/(ptpv1.y-ptpv.y);

        float ra = distance(cp,vec2(S(6)-ptp.y,DH));
        vec2 ptv = vec2(S(6)-pt.y,0.0);

        d1 = abs(pt.x-O3.x);
        dh = O3r>=d1 ? sqrt(O3r*O3r -d1*d1) : 0.0;
        vec2 O3c = O3 +d1*Onp -On*dh;

        vec2 O3cl = vec2(abs(ptp.x));

        O3c =  abs(dot(pt-O3,Onp))>O3.x-(O3+O3r*vec2(-1.0,1.0)/sqrt(2.0)).x  ? O3cl: O3c;
        vec2 O3cv = vec2(S(6)-O3c.y,0.0);
        float h4 = dot(O3cv-cp,nv);
        float sca = sqrt(ra*ra-h4*h4)/dot(O3cv-cp,tg);

        vec2 ptvf = vec2(dot(ptv-cp,tg),dot(ptv-cp,nv));
        vec2 ptv1f = vec2(dot(ptv+vec2(0.0,1.0)-cp,tg),dot(ptv+vec2(0.0,1.0)-cp,nv));
        ptvf.x*=sca;
        ptv1f.x*=sca;
        vec2 ptvn = normalize(ptv1f-ptvf);
        vec2 ptvfh = ptvf +dot(-ptvf,ptvn)*ptvn;

        dh = length(ptvfh);

        float sq =sqrt(ra*ra-dh*dh);
        vec2 ptvfc = ptvfh + ptvn*sq;
        ptvfc.x*=1.0/sca;

        vec2 pci =cp + ptvfc.x*tg + ptvfc.y*nv; 

        vec2 pci1;
        {
            vec2 O3cv = vec2(S(6)-O3cl.y,0.0);
            float h4 = dot(O3cv-cp,nv);
            float sca = sqrt(ra*ra-h4*h4)/dot(O3cv-cp,tg);

            vec2 ptvf = vec2(dot(ptv-cp,tg),dot(ptv-cp,nv));
            vec2 ptv1f = vec2(dot(ptv+vec2(0.0,1.0)-cp,tg),dot(ptv+vec2(0.0,1.0)-cp,nv));
            ptvf.x*=sca;
            ptv1f.x*=sca;
            vec2 ptvn = normalize(ptv1f-ptvf);
            vec2 ptvfh = ptvf +dot(-ptvf,ptvn)*ptvn;

            dh = length(ptvfh);

            float sq =sqrt(ra*ra-dh*dh);
            vec2 ptvfc = ptvfh + ptvn*sq;
            ptvfc.x*=1.0/sca;

            vec2 pci =cp + ptvfc.x*tg + ptvfc.y*nv; 
            pci1 = pci;

        }  
        float hv = ra>=dh ? distance(pci,ptv) : -di2;
        float he= pt.y <O2.y ? h :hv;

        h =he*sch;
        float lh = O3.y+ (O3r)/sqrt(2.0);

        mask = pt.y<lh && abs(dh1) <=di2 && abs(dh0)<=d || 
               (pt.y>lh && distance(pt,O3) < O3r);
    }


    h += h1;
    u = h >hn.x && mask ;
    oparm =u? param_p: oparm;
    hn = u ? vec2(h,-di2) : hn;
    param+=paramO;

    // ***
    // ******************

    O= V(6,6)-vec2(0.0,ds2);
    C= O+vec2(1.0)*di2/sqrt(2.0);
    l= distance(C, V(12,0)+vec2(-cc.x,cc.y));
    dn = vec2(1.0,-1.0)*sqrt(2.0)/2.0;
    paC = dot(p-C,dn); 

    mask = paC >=0.0 && dot(p-(V(12,0)+vec2(-1.0-sqrt(2.0),1.0)*d),vec2(-1.0-sqrt(2.0),1.0))>=0.0;
    eC = C+paC*dn; 
    fh = length(p-eC);
    mask = mask && fh<di2; 
    h = sch*sqrt(di2*di2-fh*fh);


    //->
    vec2 O1 =  V(12,0)-vec2(sqrt(2.0)/2.0+.5,-.5)*d;
    vec2 O1O2 = vec2(-sqrt(2.0)-1.0, 1.0);
    vec2  c1 =O1+ O1O2*dot(c-O1,vec2(-1.0,1.0))/dot(O1O2,vec2(-1.0,1.0));    
    //vec2 c1;
    vec2 OCb3 = c+vec2(1.0)*(ds2+ di2/sqrt(2.0));
    paramO = distance(OCb3,V(6,6)+vec2(0.0,-ds2/2.0));
    paramO1=0.0;

    if(dot(p-c, vec2(-1.0,1.0))<0.0)
    {
       paramO1 = distance(OCb3, vec2(-1.0*-sqrt(2.0),1.0)*di2);
       param_p = param +paramO+(-OCb3.x +(c1.x+ (p.x-c1.x)*
                       dot(O1-c1,vec2(1.0))/dot(p-c1,vec2(1.0))))*sqrt(2.0);   
    }

    h1 = di2*(  1.0- smoothstep(S(0),S(3),abs(param_p-paT)) 
              -(1.0- smoothstep(S(0),S(3),abs(param_p-paT1))) );  

    h +=h1;  
    u = h >hn.x && mask; 
    oparm = u? param_p  :oparm;

    hn = u ? vec2(h,-di2) : hn;
    param+=paramO;
    // ***
    // bottom rigth corner 
    O = V(12,0)+vec2((-sqrt(2.0)-1.0),1.0)*d;
    Op =p-O;
    CL = O+ vec2(dis2,+dis2)*.5;
    CR = vec2(O.x,di2); 

    lOp =length(Op);
    eC = O + di2*Op/lOp;
    paC = di2*acos(dot(CL-O,Op)/(lOp*length(CL-O))); //arclen
    h1 = ( smoothstep(S(3),S(0),abs((param+paC)-paT))*di2) ; 
    //->
    vec2 OCb4 = V(12,0)+vec2(-1.0-sqrt(2.0),1.0)*d/2.0;
     vec2 c1t =vec2(c.x,c1.y)-vec2(0.0,1.0)*(c1.x-c.x)*((c1-O).y/(c1-O).x);
     paramO = distance(OCb4,c+vec2(1.0)*(ds2+di2/sqrt(2.0))); 
     float h1t = 0.0;
     if (dot(p-V(12,0), vec2(1.0,1.0+sqrt(2.0)))<0.0)
     {
         param_p =  param +paramO+ (OCb4.x- (c1t.x+(p.x-c1t.x)*(c1t.y-OCb4.y)/(c1t.y-p.y)));
         float paT0 =param+paramO+distance(vec2(c.x, di2), V(12,0)+vec2(-1.0-sqrt(2.0),1.0)*d/2.0)+ d*1.5*PI/4.0
                +asin(di2/(d*1.5))*d*1.5;
         h1t = di2* 2.0*(1.0- smoothstep(S(0),S(6),abs(param_p-paT0)));                                               
     }
    h1 = h1t+ di2*( - (1.0- smoothstep(S(0),S(3),abs(param_p-paT1))) );       
    vec2 O3 =V(12,0) +di2*vec2(-1.0-sqrt(2.0),1.0)/sqrt(4.0+2.0*sqrt(2.0));
    bool m1 = dot(p-vec2(O3.x,0.0),O-V(12,0))>0.0;
    h =  m1 || (!m1 && distance(O3,p)-O3.y<0.0) ? sch*hc:  -di2;
    //
    h += h1;
    u = h >hn.x && right_corner ;
    oparm =u? param_p: oparm;
    hn = u ? vec2(h,-di2) : hn;
    param +=paramO;

    //**
    //************
    C= CR;
    dn = vec2(-1.0,0.0);
    l= dot(c-C,dn);//C.x-c.x;
    paC = dot(p-C,dn); 
    paT = param+l+di2*PI/4.0;
    mask = paC <=l  && dot(p-(V(12,0)+vec2(-1.0-sqrt(2.0),1.0)*d),vec2(-1.0-sqrt(2.0),1.0))>=0.0;
    eC = C+paC*dn; 
    fh = length(p-eC);
    mask = mask && fh<di2;
    h = sch*sqrt(di2*di2-fh*fh);
    vec2 OCb5 =vec2(c.x, di2);

    paramO =distance(OCb5, V(12,0)+vec2(-1.0-sqrt(2.0),1.0)*d/2.0);
    paT =param+paramO+ d*1.5*PI/4.0;
    paT1 = paT +d*1.5*PI/2.0;

    float al1 = asin(di2/(d*1.5))*d*1.5;

    h1= ((param_p-(paT+al1)>0.0? 2.0*smoothstep(S(3),S(0), param_p-(paT+al1))
                               : 2.0*smoothstep(S(6),S(0),-( param_p-(paT+al1))) )-
         2.0*smoothstep(S(3),S(0),abs( param_p-paT1))
         )*di2; 

    h+=h1;
    u = h >hn.x && mask;   
    oparm = u? param_p :oparm;
    hn = u ? vec2(h,-di2) : hn;
    param += paramO+(c1t.x-c.x);

    //
    //*******************
    // **
    C = C +dn*l;
    O = C + vec2(0.0,di2);
    vec2 cp =p-c;

    mask = dot(cp, vec2(1.0,0.0))<0.0 || 
           dot(cp, vec2(1.0,-1.0))<0.0;   
    float lcp =length(cp);
    eC = c+ (r-di2)*cp/lcp;
    fh = abs(lcp-(d+di2));
    mask = mask && fh<di2;
    h = sch*sqrt(di2*di2-fh*fh);
    float at = atan(dot(C-c,vec2(cp.y,-cp.x)),dot(C-c,cp));
    paC = (r-d+di2)*(at <0.0 ? -at :2.0*PI-at);

    paramO =(d+di2)*5.0*PI/4.0;
    param_p =param+paC;

    h1=  (
            (param_p-(paT+al1)>0.0? 2.0*smoothstep(S(3),S(0), param_p-(paT+al1))
                               : 2.0*smoothstep(S(6),S(0),-( param_p-(paT+al1))) )-
            2.0* smoothstep(S(3),S(0),abs(param_p-paT1))+
            2.0*smoothstep(S(3),S(0),abs(param_p-(paT1+ d*1.5*PI/2.0-al1)))
         )*di2; 
    h+= h1;
    //
    u = h >hn.x && t>= param_p && mask ;
    oparm =u? param_p: oparm;
    hn = u ? vec2(h,hn.x) : hn; 
    param+=paramO;

    //**
    //*****************

    O = c+vec2(1.0)*dis2; 
    C = O +vec2(1.0)*dis2*.5;
    dn = vec2(1.0,-1.0)/sqrt(2.0);
    //find arc center 
    o = c +vec2(0.0,-ds2/2.0)+ vec2(1.0,-1.0)*(d-ds2/2.0);
    a = (-1.0/sqrt(2.0)+1.0)*sqrt(2.0);
    ac =o + vec2(-a+1.0,a+1.0)*r*sqrt(2.0)/2.0;
    //
    l = sqrt(2.0)*(O.y-(ac.y-d));
    paC = dot(p-C,dn); 


    mask = paC >=0.0 && dot(p-(V(12,0) + vec2(-1.0-sqrt(2.0),1.0)*d +vec2(-1.0-sqrt(2.0),1.0)*d),vec2(-1.0-sqrt(2.0),1.0))>=0.0;
    eC = C+paC*dn; 
    fh = length(p-eC);
    mask = mask && fh<di2;
    h = sch*sqrt(di2*di2-fh*fh);

    vec2 OCb7 =c+vec2(1.0)*(d+di2)/sqrt(2.0);
    param_p =param +((c1.x+ (p.x-c1.x)*dot(OCb7-c1, vec2(1.0))/dot(p-c1, vec2(1.0)))-OCb7.x)*sqrt(2.0);

    h1= (
          -2.0*smoothstep(S(3),S(0),abs(param_p-paT1))+
          2.0*smoothstep(S(3),S(0),abs(param_p-(paT1+ d*1.5*PI/2.0-al1)))
         )*di2;         
    h+=h1;
    u = h >hn.x && t>= param_p && mask; //( t>= param_p || distance(p,tbp)<di2 )
    oparm = u? param_p :oparm;
    hn = u ? vec2(h,hn.x) : hn;

    param += distance(C,V(12,0)+vec2(-sqrt(2.0)-1.0,1.0)*(d+di2));
    // **
    //*************

    // mid corner  
    O= O+dn*l;
    Op =p-O;
    CL = O+ vec2(dis2,+dis2)*.5;
    CR = O+vec2(0.0,-di2); 

    lOp =length(Op);
    paC = di2*acos(dot(CL-O,Op)/(lOp*length(CL-O))); //arclen
    h1 = smoothstep(S(1)*1.5,S(0),abs((param+paC)-paT))*di2; 
    vec2 OCb8 = V(12,0)+vec2(-1.0-sqrt(2.0),1.0)*d*1.5;

    param_p = dot(p-V(12,0),vec2(1.0,1.0+sqrt(2.0)))<0.0 ? param +(OCb8.x-(c1.x+(p.x-c1.x)*dot(OCb8-c1,vec2(0.0,-1.0))/dot(p-c1,vec2(0.0,-1.0))))
                                                        : param_p;

    paramO = OCb8.x - ac.x;

    h1= (
         -2.0*smoothstep(S(3),S(0),abs(param_p-paT1))+
          2.0*smoothstep(S(3),S(0),abs(param_p-(paT1+ d*1.5*PI/2.0-al1)))
        )*di2;   

    O3 =V(12,0)+ d*vec2(-1.0-sqrt(2.0),1.0)+ di2*vec2(-1.0-sqrt(2.0),1.0)/sqrt(4.0+2.0*sqrt(2.0));

    m1 = dot(p-vec2(O3.x,d),O-V(12,0))>=0.0;
    m1 =m1 || (!m1 && distance(p,O3)<=(O3.y-d));
    h =  m1   ? sch*hc:  -di2;

    h += m1 ?h1:0.0;
    u = h >hn.x && mid_corner && p.x>O.x ;
    oparm =u? param_p: oparm;
    hn = u ? vec2(h,-di2) : hn;
    param += paramO;

    // **
    //***************

    O = c+vec2(1.0)*dis2 +(c.y+dis2-ac.y+d)*vec2(1.0,-1.0);
    C = O+vec2(0.0,-di2);

    l= C.x-ac.x;
    dn = vec2(-1.0,0.0);
    paC = dot(p-C,dn); 

    paT =param + (d+di2)*acos(dot(c-ac,C-ac)/(length(c-ac)*length(C-ac))) +d+di2;

    mask =  paC<=l && dot(p-(V(12,0)+vec2(-1.0-sqrt(2.0),1.0)*2.0*d),vec2(1.0,0.0))<=0.0 ;
    eC = C+paC*dn; 
    fh = length(p-eC);
    mask = mask && fh<di2;
    h = sch*sqrt(di2*di2-fh*fh);

    h += smoothstep(S(2),S(0),abs(paT -(param+paC)))*di2; 
    u = h >hn.x && mask;
    hn = u ? vec2(h,-di2) : hn;
    oparm = u? param_p :oparm;

    // **
    //*************
    vec2 Ctmp=C;
    C+=l*dn;
    O+=l*dn;
    cp =p-ac;
    mask = dot(cp, vec2(1.0,0.0))<0.0 && 
           dot(p-c, vec2(1.0,-1.0))>0.0;  



    lcp =length(cp);
    eC = ac + (r-di2)*cp/lcp;
    fh = abs(lcp-(d+di2));
    mask = mask && fh<di2;
    h = sch*sqrt(di2*di2-fh*fh);

    vec2 vi = normalize(p-c1);
    vec2 vj = vec2(vi.y,-vi.x);
    float j =dot(p-ac,vj);
    float i = sqrt((d+di2)*(d+di2)-j*j);
    float al = acos(dot(normalize(ac-C),normalize(ac-(ac+i*vi+j*vj))))*(di2+d);
    param_p   = param_p >param?  param + al : param_p;    


    float al6 =acos(dot(c-ac,C-ac)/(length(c-ac)*length(C-ac)));
    paramO = al6*(d+di2);

    h1 = smoothstep(S(2),S(0),abs(param_p-paT))*di2; 
    h += h1;  
    u = h >hn.x && mask ;
    oparm =u? param_p: oparm;
    hn = u ? vec2(h,-di2) : hn;
    param += paramO;

    // **
    //***********

    O= c+ vec2(1.0)*dis2*.5;
    C= c;
    l= r+d;
    dn = vec2(-1.0,1.0)/sqrt(2.0);
    paC = dot(p-C,dn); 
    mask = paC >=0.0 && paC<=l;
    eC = C+paC*dn; 
    fh = length(p-eC);
    mask = mask && fh<di2;                 
    h = sch*sqrt(di2*di2-fh*fh);

    paramO = al6*(d+di2);
    param_p = param+paC;

    paramO = dot(-C,vec2(-1.0,1.0)/sqrt(2.0));
    h1 = smoothstep(S(2),S(0),abs(paT -param_p))*di2; 
    h += h1;
    u = h >hn.x && t>= param_p &&  mask;
    oparm = u? param_p : oparm;
    hn = u ? vec2(h,hn.x) : hn;

    // animation.
    const float tl = d;
    float mf =smoothstep(-.04,.0,oparm-t+.02*noise(vec3(p*23.0,hn.x)));
    float hq =  (oparm >t-tl) ? mf >.9  ? hn.y :mix( hn.x ,-di2, mf )
                             :hn.x;

    return t>0.0 ? t<_q0T+tl ? hq 
                             : hn.x
                 :-di2;
}




void draw(vec2 p,float t,inout vec3 pixel)
{         
  float offx = (iResolution.x*_pixSize-S(12))*.5;
  p-=vec2(offx,.05);

  p*=SC;
  float m= sqrt(2.0)/(3.0+sqrt(2.0));
  float d = .5*S(6)*m;

  //Coordinate transformation to account symmetry. 
  vec2 dir1 = V(6,6)-V(0,0);
  float cr1= p.x*dir1.y -p.y*dir1.x;
  int q1 = cr1<0.0 ? 1 :0;
  vec2 dir2 = V(12,0)-V(6,6) ;
  float cr2 = (p.x-S(12))*dir2.y -(p.y-S(0))*dir2.x;
  int q2 = cr2<0.0 ? 1 :0;
  int q = q1 <<1 |q2;
  // 

  float rot = q==1 ? -PI/2.0 :q==2 ?PI/2.0 : q==0 ?0.0: PI;
  _cs =  vec2(cos(rot),sin(rot));

  // apply rotational symetry
  p-=V(6,6);
  p= R(p,_cs);
  p+=V(6,6);//


  float h = height(p,t,q,pixel);

  // normal computation
  float e = 0.0001;
  #if 0
  float hxx= height(p+vec2(e,0.0),t,q,pixel);
  float hx = height(p+vec2(-e,0.0),t,q,pixel);
  float hyy = height(p+vec2(0.0,e),t,q,pixel);
  float hy = height(p+vec2(0.0,-e),t,q,pixel);
  vec3 n1 = normalize(vec3((hx-hxx)/(e*2.0),(hy-hyy)/(e*2.0),1.0));
  #else
    // prevent 4x compiler expansion of height.
    vec4 h4;
    for( int i=min(iFrame,0); i<4; i++ )
    {
        vec2 ev = e*(vec2( ((i+1)>>1), ((i+1)>>1) +((i+1)&1) -(i&1))-1.0);
        h4[i] = height(p+ev,t,q,pixel);

    }
    vec3 n1 = normalize(vec3((h4[0]-h4[3])/(2.0*e),
                        (h4[1]-h4[2])/(2.0*e),1.0));
  #endif 

 pixel =lighting(vec3(p,h),n1, t,q);

}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   _pixSize = 1.0/iResolution.y;
   _ar = iResolution.x/iResolution.y;


   float t = iTime*.2;
   vec3 tot=vec3(0.0);
#if AA>1
    for( int m=min(iFrame,0); m<AA; m++ )
    for( int n=min(iFrame,0); n<AA; n++ )
    {
        // pixel coordinates
        vec2 o = vec2(float(m),float(n)) / float(AA) - 0.5;
        vec2 uv = (fragCoord+o)/iResolution.y;
#else    
        vec2 uv = fragCoord/iResolution.y;
#endif
       vec3 pixel =vec3(.8);
       draw(uv,t,pixel);
       tot+=pixel;

#if AA>1
    }
    tot /= float(AA*AA);
#endif
   // gamma
   tot = pow( tot, vec3(0.4545) );

   // vignette
   vec2 q = fragCoord/iResolution.xy;
   float vi= 0.5 + 0.5*pow(16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y),0.15);

   // Output to screen
   fragColor = vec4(tot*vi,1.0);

}
